# Generated by GitHub Copilot - Nov-17-2026
"""Rich resume model: turns plain/extracted text into header, contacts, entries and skill groups.

Handles real-world PDF extraction artefacts: wrapped lines, bullets without bullet glyphs, dates on the
same line as titles, "Company  On-site • City" rows, label/value skill groups and builder watermarks.
"""
import re

from .lang_data import EMAIL_RE, SKILLS
from .resume_struct import parse_resume

MONTH = (r"(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?|janv|févr|mars|avr|mai|juin|juil|"
         r"août|sept|oct|nov|déc|ene|abr|ago|dic")
DATE_POINT = rf"(?:(?:{MONTH})\s+\d{{4}}|\d{{1,2}}/\d{{4}}|\d{{4}}(?:年\d{{1,2}}月)?)"
OPEN_END = r"(?:present|current|now|today|ongoing|aujourd'hui|présent|actualidad|presente|至今|现在|वर्तमान|حتى الآن|الآن)"
DATE_RANGE_RE = re.compile(rf"({DATE_POINT}\s*(?:[-–—~至]|to|à|a|al)\s*(?:{DATE_POINT}|{OPEN_END})|{DATE_POINT}|{OPEN_END})\s*$",
                           re.IGNORECASE)
DATE_ANY_RE = re.compile(rf"{DATE_POINT}\s*(?:[-–—~至]|to)\s*(?:{DATE_POINT}|{OPEN_END})", re.IGNORECASE)
LEADING_DATE_RE = re.compile(rf"^({DATE_POINT}\s*(?:[-–—~至]|to)\s*(?:{DATE_POINT}|{OPEN_END})|{DATE_POINT})\s+(.+)$",
                             re.IGNORECASE)
WORKMODE_RE = re.compile(r"\b(on-?site|remote|hybrid|en remoto|télétravail|presencial)\b.*$", re.IGNORECASE)
EMPLOYMENT_RE = re.compile(r"^(full[- ]?time|part[- ]?time|internship|intern|contract|freelance|temporary|"
                           r"volunteer|apprenticeship|self-employed|temps plein|stage|prácticas|实习|全职)$", re.IGNORECASE)
TECH_RE = re.compile(r"^((?:[\w/&+ ]{0,25})?(?:technolog|tools|tech stack|stack|skills used|environment|"
                     r"technologies|outils|herramientas|技术)[\w/&+ ]{0,30}?)\s*[:：]\s*(.+)$", re.IGNORECASE)
URL_TOKEN_RE = re.compile(r"(?:https?://|www\.)\S+|(?:linkedin\.com|github\.com|gitlab\.com)/\S+", re.IGNORECASE)
PHONE_TOKEN_RE = re.compile(r"\+?\d[\d\s().-]{7,}\d")
WATERMARK_RE = re.compile(r"(www\.)?(enhancv|zety|resume\.io|novoresume|canva|resumegenius|kickresume)\.com|"
                          r"^powered by\b|^page \d+( of \d+)?$|^\d+\s*/\s*\d+$", re.IGNORECASE)
TERMINAL = (".", "!", "?", "。", "।", "؟")
CONNECTORS = {"and", "or", "of", "in", "for", "to", "the", "with", "at", "on", "&", "a", "an", "by", "from", "using",
              "including", "et", "de", "des", "du", "y", "en", "con", "para"}
ENTRY_SECTIONS = {"experience", "education", "projects", "certifications"}
SIDEBAR_FRIENDLY = {"skills", "languages", "certifications", "achievements"}


def has_date(text: str) -> bool:
    """True if the line carries a date range or a trailing year/'Present'."""
    return bool(DATE_ANY_RE.search(text) or DATE_RANGE_RE.search(text) or LEADING_DATE_RE.match(text))


def split_date(text: str) -> tuple[str, str]:
    """Split a trailing (or leading) date from a line -> (rest, date)."""
    m = DATE_ANY_RE.search(text)
    if m:
        return (text[:m.start()] + " " + text[m.end():]).strip(" |,-–•"), m.group(0).strip()
    m = LEADING_DATE_RE.match(text)
    if m:
        return m.group(2).strip(" |,-–•"), m.group(1).strip()
    m = DATE_RANGE_RE.search(text)
    if m:
        return text[:m.start()].strip(" |,-–•"), m.group(1).strip()
    return text, ""


def _words(text: str) -> list[str]:
    return text.split()


def _title_case_short(text: str) -> bool:
    """Short, mostly capitalised line without sentence punctuation (typical job/project title)."""
    words = [w for w in _words(text) if re.search(r"[A-Za-zÀ-ÿ]", w)]
    if not words or len(words) > 8 or text.rstrip().endswith(TERMINAL) or "," in text:
        return False
    caps = sum(1 for w in words if w[0].isupper() or w[0].isdigit() or w.lower() in CONNECTORS)
    return caps / len(words) >= 0.75


def _ends_open(text: str) -> bool:
    """True if a line clearly continues on the next one (trailing comma or connector word)."""
    t = text.rstrip()
    return t.endswith((",", "&", "-", "/", "(")) or (t.split() or [""])[-1].lower() in CONNECTORS


def join_wrapped(items: list[dict], width: int) -> list[dict]:
    """Re-join lines that a PDF/DOCX wrapped mid-sentence."""
    out: list[dict] = []
    for item in items:
        if not out or item["type"] == "bullet":
            out.append(dict(item))
            continue
        prev, text = out[-1], item["text"]
        p = prev["text"].rstrip()
        first = text[:1]
        join = False
        if text.startswith(":") and URL_TOKEN_RE.search(p.split()[-1] if p.split() else ""):
            prev["text"] = p + text.lstrip(": ")
            continue
        if first.islower() or first in ",;)]" or _ends_open(p):
            join = not has_date(text) or first.islower()
        elif not p.endswith(TERMINAL) and not has_date(text) and not _title_case_short(text):
            # bullet or long sentence continuing onto the next line
            join = prev["type"] == "bullet" or len(p) >= 0.72 * width
        elif (prev["type"] == "text" and _title_case_short(p) and not p.endswith(TERMINAL)
              and len(_words(text)) <= 3 and not has_date(text) and not has_date(p) and len(p) >= 0.72 * width):
            join = True  # e.g. "Enterprise Kubernetes & Serverless" + "Platform"
        if join:
            prev["text"] = f"{p} {text}".strip()
        else:
            out.append(dict(item))
    return out


def _line_width(items: list[dict]) -> int:
    lengths = sorted(len(i["text"]) for i in items) or [80]
    return max(30, lengths[int(len(lengths) * 0.9) - 1 if len(lengths) > 1 else 0])


def _split_location(text: str) -> tuple[str, str]:
    """'Accenture On-site • Hyderabad' -> ('Accenture', 'On-site • Hyderabad')."""
    m = WORKMODE_RE.search(text)
    if m:
        return text[:m.start()].strip(" |,-–•"), m.group(0).strip()
    return text, ""


def _looks_like_location(text: str) -> bool:
    if WORKMODE_RE.search(text) or "•" in text:
        return True
    return bool(re.fullmatch(r"[A-ZÀ-Ý][\w .'-]+,\s*[A-ZÀ-Ý][\w .'-]+", text)) and len(text.split()) <= 5


def _new_entry() -> dict:
    return {"title": "", "meta": "", "subtitle": "", "date": "", "location": "", "details": [], "bullets": [],
            "tech": None, "link": "", "_header": []}


def _resolve_header(entry: dict) -> None:
    """Map up to three header lines onto title / meta / subtitle / date / location."""
    lines = entry.pop("_header")
    for idx, raw in enumerate(lines):
        rest, date = split_date(raw)
        if date and not entry["date"]:
            entry["date"] = date
        url = URL_TOKEN_RE.search(rest)
        if url:
            entry["link"] = url.group(0)
            rest = rest.replace(url.group(0), "").strip(" :|")
            if re.fullmatch(r"(certification|credential|verify|url|link|\s)*", rest, re.IGNORECASE):
                continue
        if not rest:
            continue
        parts = [p.strip() for p in re.split(r"\s+\|\s+|\s*\|\s*", rest) if p.strip()]
        if idx == 0:
            entry["title"] = parts[0]
            for part in parts[1:]:
                if EMPLOYMENT_RE.match(part):
                    entry["meta"] = part
                elif not entry["subtitle"] and len(lines) == 1:
                    entry["subtitle"] = part
                elif _looks_like_location(part) and not entry["location"]:
                    entry["location"] = part
                else:
                    entry["meta"] = " | ".join(filter(None, [entry["meta"], part]))
            continue
        text = " | ".join(parts)
        subtitle, loc = _split_location(text)
        if loc:
            entry["location"] = entry["location"] or loc
            if subtitle and not entry["subtitle"]:
                entry["subtitle"] = subtitle
            continue
        if date and not entry["location"] and len(parts) == 1:
            entry["location"] = text  # "Aug 2023 - Present Hyderabad, India"
        elif not entry["subtitle"]:
            entry["subtitle"] = text
        elif _looks_like_location(text) and not entry["location"]:
            entry["location"] = text
        else:
            entry["details"].append(text)


def parse_entries(items: list[dict], key: str) -> tuple[list[dict], str]:
    """Group a section's lines into entries. Returns (entries, orphan_location)."""
    entries: list[dict] = []
    current = None
    phase = "header"
    orphan = ""
    for pos, item in enumerate(items):
        text = item["text"].strip()
        if not text:
            continue
        if pos == 0 and item["type"] == "text" and WORKMODE_RE.match(text) and len(text.split()) <= 5:
            orphan = text  # location that PDF extraction pushed below the next heading
            continue
        tech = TECH_RE.match(text)
        if tech and current is not None:
            current["tech"] = {"label": tech.group(1).strip(), "value": tech.group(2).strip()}
            phase = "body"
            continue
        if (item["type"] == "text" and current is not None and current["tech"] and pos > 0
                and TECH_RE.match(items[pos - 1]["text"].strip()) and len(_words(text)) <= 3 and not has_date(text)):
            current["tech"]["value"] += " " + text  # wrapped tail of a "Technologies used:" line
            continue
        if item["type"] == "bullet":
            if current is None:
                current = _new_entry()
                entries.append(current)
            current["bullets"].append(text)
            phase = "body"
            continue
        starts = has_date(text) or " | " in text or (_title_case_short(text) and len(text) <= 90)
        header_full = current is not None and (
            len(current["_header"]) >= 3
            or (len(current["_header"]) >= 2 and _title_case_short(text) and len(_words(text)) >= 3))
        if current is None or (phase == "body" and starts) or (phase == "header" and starts and header_full) or (
                phase == "header" and has_date(text) and any(has_date(h) for h in current["_header"])):
            current = _new_entry()
            current["_header"].append(text)
            entries.append(current)
            phase = "header"
            continue
        header_like = (has_date(text) or "|" in text or "•" in text or URL_TOKEN_RE.search(text)
                       or (len(_words(text)) <= 8 and not text.endswith(TERMINAL)))
        if phase == "header" and len(current["_header"]) < 3 and header_like:
            current["_header"].append(text)
            continue
        phase = "body"
        if key in ("experience", "projects") and len(_words(text)) >= 5:
            current["bullets"].append(text)  # bullet glyph lost during extraction
        else:
            current["details"].append(text)
    for entry in entries:
        if "_header" in entry:
            _resolve_header(entry)
    return entries, orphan


def parse_skill_groups(items: list[dict]) -> list[dict]:
    """'Label : a, b' lines, or a label line followed by comma lists -> [{label, items}]."""
    groups: list[dict] = []
    lines = [i["text"].strip() for i in items if i["text"].strip()]
    for idx, line in enumerate(lines):
        m = re.match(r"^([^:,：]{2,40}?)\s*[:：]\s*(.*)$", line)
        nxt = lines[idx + 1] if idx + 1 < len(lines) else ""
        cont = groups and (groups[-1]["_raw"].rstrip().endswith(",") or _ends_open(groups[-1]["_raw"]))
        if m and not URL_TOKEN_RE.search(line):
            groups.append({"label": m.group(1).strip(), "_raw": m.group(2)})
        elif ("," not in line and len(_words(line)) <= 5 and "," in nxt and not cont):
            groups.append({"label": line, "_raw": ""})
        elif groups:
            groups[-1]["_raw"] = f"{groups[-1]['_raw']} {line}".strip()
        else:
            groups.append({"label": "", "_raw": line})
    out = []
    for g in groups:
        values = [v.strip(" .") for v in re.split(r"\s*[,;•|·]\s*", g.pop("_raw")) if v.strip(" .")]
        if values or g["label"]:
            out.append({"label": g["label"], "items": values})
    return out


def _paragraphs(items: list[dict]) -> list[str]:
    """Join wrapped text lines into paragraphs."""
    paras: list[str] = []
    for item in items:
        text = item["text"].strip()
        if paras and not paras[-1].endswith(TERMINAL):
            paras[-1] = f"{paras[-1]} {text}"
        else:
            paras.append(text)
    return paras


def parse_contacts(lines: list[str]) -> list[dict]:
    """Extract typed contact items (email, phone, linkedin, github, web, location)."""
    contacts: list[dict] = []
    seen = set()

    def add(kind, text, href=""):
        if text and text.lower() not in seen:
            seen.add(text.lower())
            contacts.append({"kind": kind, "text": text, "href": href})

    for line in lines:
        for seg in re.split(r"\s*[|•·]\s*|\s{2,}", line):
            seg = seg.strip(" ,;")
            if not seg:
                continue
            for email in EMAIL_RE.findall(seg):
                add("email", email, f"mailto:{email}")
                seg = seg.replace(email, " ")
            for url in URL_TOKEN_RE.findall(seg):
                clean = url.rstrip(".,;)")
                href = clean if clean.lower().startswith("http") else f"https://{clean}"
                kind = "linkedin" if "linkedin" in clean.lower() else "github" if "github" in clean.lower() else "web"
                add(kind, re.sub(r"^https?://(www\.)?", "", clean).rstrip("/"), href)
                seg = seg.replace(url, " ")
            for phone in PHONE_TOKEN_RE.findall(seg):
                if len(re.sub(r"\D", "", phone)) >= 8:
                    add("phone", phone.strip(), "tel:" + re.sub(r"[^\d+]", "", phone))
                    seg = seg.replace(phone, " ")
            for word, kind in (("linkedin", "linkedin"), ("github", "github"), ("portfolio", "web")):
                if re.search(rf"\b{word}\b", seg, re.IGNORECASE):
                    add(kind, word.capitalize() if kind != "linkedin" else "LinkedIn")
                    seg = re.sub(rf"\b{word}\b", " ", seg, flags=re.IGNORECASE)
            rest = re.sub(r"\s+", " ", seg).strip(" ,;:-")
            if rest and len(rest) <= 60:
                add("location", rest)
    return contacts


def build_model(text: str) -> dict:
    """Parse resume text into the rich model used by the HTML/DOCX renderers."""
    lines = [l for l in text.split("\n") if not WATERMARK_RE.search(l.strip())]
    base = parse_resume("\n".join(lines))
    sections: list[dict] = []
    for sec in base["sections"]:
        if sections and sections[-1]["key"] == sec["key"] and sec["key"] != "other":
            sections[-1]["_items"].extend(sec["items"])  # same heading repeated on a new page
            continue
        sections.append({"key": sec["key"], "heading": sec["heading"], "_items": list(sec["items"])})

    out_sections = []
    prev_entries = None
    for sec in sections:
        raw = sec.pop("_items")
        key = sec["key"]
        # skill lists wrap differently (label lines + comma lists), so they are joined by their own parser
        items = raw if key in ("skills", "languages") else join_wrapped(raw, _line_width(raw))
        if key in ("skills", "languages"):
            sec.update(kind="skills", groups=parse_skill_groups(items))
        elif key == "summary":
            sec.update(kind="text", paragraphs=_paragraphs(items))
        elif key in ENTRY_SECTIONS or any(has_date(i["text"]) or " | " in i["text"] for i in items):
            entries, orphan = parse_entries(items, key)
            if orphan and prev_entries and not prev_entries[-1]["location"]:
                prev_entries[-1]["location"] = orphan
            sec.update(kind="entries", entries=entries)
            prev_entries = entries
        elif items and sum(i["type"] == "bullet" for i in items) >= len(items) / 2:
            sec.update(kind="list", items=[i["text"] for i in items])
        else:
            sec.update(kind="text", paragraphs=_paragraphs(items))
        out_sections.append(sec)

    return {
        "name": base["name"],
        "headline": base["headline"],
        "contacts": parse_contacts([base["contact_line"]] if base["contact_line"] else []),
        "sections": out_sections,
    }


INLINE_BOLD_RE = re.compile(r"\*\*(.+?)\*\*")


def segments(text: str, keywords: list[str] | None = None) -> list[tuple[str, bool]]:
    """Split text into (chunk, bold) pairs: honours **markdown** and optionally bolds keywords."""
    parts: list[tuple[str, bool]] = []
    pos = 0
    for m in INLINE_BOLD_RE.finditer(text):
        if m.start() > pos:
            parts.append((text[pos:m.start()], False))
        parts.append((m.group(1), True))
        pos = m.end()
    if pos < len(text):
        parts.append((text[pos:], False))
    if not keywords:
        return parts
    pattern = keyword_pattern(tuple(keywords))
    if pattern is None:
        return parts
    out: list[tuple[str, bool]] = []
    for chunk, bold in parts:
        if bold:
            out.append((chunk, True))
            continue
        last = 0
        for m in pattern.finditer(chunk):
            if m.start() > last:
                out.append((chunk[last:m.start()], False))
            out.append((m.group(0), True))
            last = m.end()
        if last < len(chunk):
            out.append((chunk[last:], False))
    return out


_PATTERN_CACHE: dict[tuple, re.Pattern | None] = {}


def keyword_pattern(keywords: tuple) -> re.Pattern | None:
    """Single alternation regex for keyword bolding (longest terms first, cached)."""
    if keywords not in _PATTERN_CACHE:
        terms = sorted({k.strip() for k in keywords if len(k.strip()) >= 2}, key=len, reverse=True)
        _PATTERN_CACHE[keywords] = re.compile(
            r"(?<![\w+#])(?:" + "|".join(re.escape(t) for t in terms) + r")(?![\w+#])", re.IGNORECASE) if terms else None
        if len(_PATTERN_CACHE) > 64:
            _PATTERN_CACHE.pop(next(iter(_PATTERN_CACHE)))
    return _PATTERN_CACHE[keywords]


def bold_keywords_for(text: str, job_description: str = "") -> list[str]:
    """Skills present in the resume (plus JD keywords present) - used for 'bold key skills'."""
    from .ats import _contains, extract_keywords  # local import avoids a cycle
    from .lang_data import detect_language
    found = [s for s in SKILLS if len(s) > 2 and _contains(text, s)]
    if job_description.strip():
        found += [k["term"] for k in extract_keywords(job_description, detect_language(job_description))
                  if _contains(text, k["term"])]
    return found


def plain(text: str) -> str:
    """Remove **markdown** markers (for exporters that cannot render bold)."""
    return INLINE_BOLD_RE.sub(r"\1", text)
